            else:
                print("Failed to retrieve data from DHT sensor.")
    except DHTNotFound:
        print("DHT sensor not found.")
        return False
    except InvalidChecksumError:
        print("Invalid checksum received from DHT sensor.")
        return False
    except Exception as e:
