import time
from gpiozero import DigitalOutputDevice
from signal import signal, SIGINT

# Define GPIO pins
GPIO_5 = 5
GPIO_6 = 6
GPIO_20 = 20
GPIO_21 = 21

# Initialize GPIO devices
outputs = [
    DigitalOutputDevice(pin, initial_value=False) for pin in [GPIO_5, GPIO_6, GPIO_20, GPIO_21]
]

def set_output_state(pin, state):
    try:
        outputs[pin].value = state
        print(f"Set output {pin} to {state}")
    except Exception as e:
        print(f"Error setting output {pin}: {e}")

def main():
    try:
        # Set all outputs to high initially
        for pin in range(len(outputs)):
            set_output_state(pin, True)

        # Simulate reading from a sensor or other source
        # For demonstration, we'll just toggle each output every second
        while True:
            for pin in range(len(outputs)):
                set_output_state(pin, not outputs[pin].value)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Interrupt received, exiting...")
    finally:
        # Release all GPIO resources
        for output in outputs:
            output.close()

if __name__ == "__main__":
    signal(SIGINT, lambda signum, frame: main())
    main()

import smbus2
import time
from gpiozero import Button
from signal import signal, SIGINT

# Define the I2C bus number and the PCF8574 address
I2C_BUS = 1
PCF8574_ADDRESS = 0x20

# Initialize the I2C bus
try:
    bus = smbus2.SMBus(I2C_BUS)
except FileNotFoundError:
    print("Error: I2C bus not found.")
    exit(1)

# Initialize the button to trigger the measurement
button = Button(23)  # Assuming GPIO pin 23 is connected to the button

def read_pcf8574():
    try:
        # Read the data from the PCF8574
        data = bus.read_byte(PCF8574_ADDRESS)
        return data
    except OSError as e:
        print(f"Error reading from PCF8574: {e}")
        return None

def validate_reading(reading):
    # Example validation: check if the reading is within a valid range
    if reading is not None and 0 <= reading <= 255:
        return True
    else:
        print("Invalid reading received.")
        return False

def main():
    while True:
        if button.is_pressed:
            reading = read_pcf8574()
            if validate_reading(reading):
                print(f"Reading: {reading}")
        time.sleep(0.1)

if __name__ == "__main__":
    try:
        signal(SIGINT, lambda signum, frame: exit(0))  # Handle Ctrl+C
        main()
    finally:
        # Release the I2C bus and button
        bus.close()
        button.close()

